def create_category(graph_root: GraphRoot, slug: str, name: str, parent_slug: str | None = None) -> str {
    # normalized slug is wire format lowercased trimmed
    clean: str = slug.strip().lower();
    if clean == "" {
        return "";
    }
    cats: list[Category] = [graph_root ->][?:Category];
    for c in cats {
        if c.slug == clean {
            return clean;
        }
    }
    parent: Category | None = None;
    p_clean: str = "";
    if parent_slug is not None {
        p_clean = parent_slug.strip().lower();
        parent = find_category(graph_root, p_clean);
        if parent is None {
            return "";
        }
        # one level nesting enforced: parent must be top level
        if parent.parent_slug != "" {
            return "";
        }
    }
    nd = Category(slug=clean, name=name, parent_slug=p_clean);
    graph_root ++> nd;
    if parent is not None {
        # narrow optional before typed connect
        p_ok: Category = parent;
        nd +>:BelongsToParent:+> p_ok;
    } else {
        # top level no edge
        skip_check: int = 0;
    }
    return clean;
}

def create_listing(graph_root: GraphRoot, lid: str, title: str, category_slug: str, tags: list[str] | None = None) -> str {
    clean_cat: str = category_slug.strip().lower();
    cat = find_category(graph_root, clean_cat);
    if cat is None {
        return "";
    }
    # normalize tags lowercased trimmed dedup capped at 5
    normed: list[str] = [];
    seen: dict[str, bool] = {};
    if tags is not None {
        for t in tags {
            tt: str = t.strip().lower();
            if tt == "" { continue; }
            if tt in seen { continue; }
            seen[tt] = True;
            normed.append(tt);
        }
    }
    capped: list[str] = [];
    for n in normed {
        if len(capped) < 5 {
            capped.append(n);
        }
    }
    # avoid duplicate lid
    existing = find_listing(graph_root, lid);
    if existing is not None {
        return lid;
    }
    lst = Listing(lid=lid, title=title, category_slug=clean_cat);
    graph_root ++> lst;
    cat_ok: Category = cat;
    lst +>:ListedIn:+> cat_ok;
    for tn in capped {
        tg = find_tag(graph_root, tn);
        tag_node: Tag;
        if tg is None {
            tag_node = Tag(name=tn);
            graph_root ++> tag_node;
        } else {
            tag_node = tg;
        }
        lst +>:Tagged:+> tag_node;
    }
    return lid;
}

