def create_category(graph_root: GraphRoot, slug: str, cname: str, parent_slug: str | None = None) -> Category | None {
    for c in [graph_root ->:RootCatLink:->][?:Category] {
        if c.slug == slug { return None; }
    }
    cat: Category = Category(slug=slug, cname=cname, cid=slug);
    graph_root +>:RootCatLink:+> cat;
    if parent_slug is not None {
        if parent_slug == slug { return cat; }
        p: Category | None = find_category(graph_root, parent_slug);
        if p is not None {
            parents_of_p: list[Category] = [p <-:ParentLink-][?:Category];
            if len(parents_of_p) == 0 {
                parent_node: Category = p;
                parent_node +>:ParentLink:+> cat;
            }
        }
