    can boot_root with Root entry {
        print("root boot TrashCascade");
        disengage;
    }
}

walker CollectAll {
    has claimed: dict[str, bool] = {};
    has out: list[str] = [];

    can collect with Page entry {
        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
        self.out.append(here.pid);
        print(here.pid);
        nxt: list[Page] = [here ->:Parent:->][?:Page];
        visit :0: nxt else { disengage; }
    }
    can boot_root with Root entry {
        print("root boot CollectAll");
        disengage;
    }
}

def make_page(pid: str, title: str) -> Page {
    # # single owner factory - all pages anchored to root
    nd = Page(pid=pid, title=title);
    root ++> nd;
    return nd;
}

def add_child(parent: Page, child: Page) -> None {
    parent +>:Parent:+> child;
}

def trash_cascade(start: Page) -> list[str] {
    # # one cascade, one owner - canonical recursive trash
    w = start spawn TrashCascade(claimed={}, result=[]);
    print(w.result);
    return w.result;
}

def trash_single_unsafe(target: Page) -> bool {
    # # renamed raw writer - single-level, explicitly non-cascading
    if target.isTrashed {
        print("already trashed");
        return False;
    }
    target.isTrashed = True;
    target.trashedAt = "now";
    print(target.pid);
    return True;
}

def get_descendants(start: Page) -> list[str] {
    w = start spawn CollectAll(claimed={}, out=[]);
    print(w.out);
    res: list[str] = [];
    for p in w.out {
        if p != start.pid {
            res.append(p);
        }
    }
    return res;
}

def is_trashed(page: Page) -> bool {
    return page.isTrashed;
}

