walker ReachFromMachine {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];
    can start with Machine entry {
        print("finder machine " + here.mid);
        kids: list[State] = [];
        for ch in [here ->:Contains:->][?:State] { kids.append(ch); }
        if len(kids) > 0 { visit :0: kids; } else { disengage; }
    }
    can step with State entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        self.collected.append(here.sid);
        print("reach " + here.sid);
        nxt: list[State] = [];
        for ch in [here ->:Transits:->][?:State] { nxt.append(ch); }
        if len(nxt) > 0 { visit :0: nxt; } else { disengage; }
    }
}

walker ReachFromState {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];
    can step with State entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        self.collected.append(here.sid);
        print("reach " + here.sid);
        nxt: list[State] = [];
        for ch in [here ->:Transits:->][?:State] { nxt.append(ch); }
        if len(nxt) > 0 { visit :0: nxt; } else { disengage; }
    }
}

walker RankWalker {
    has claimed: dict[str, bool] = {};
    has best: list[Finding] = [];
    can start with GraphAnchor entry {
        print("finder root");
        kids: list[Machine] = [];
        for ch in [here ->:Contains:->][?:Machine] { kids.append(ch); }
        if len(kids) > 0 { visit :0: kids; } else { disengage; }
    }
    can step_machine with Machine entry {
        if here.mid in self.claimed { skip; }
        self.claimed[here.mid] = True;
        print("finder machine " + here.mid);
        if here.occupied { print("skip occupied " + here.mid); disengage; }
        if here.frozen { print("skip frozen " + here.mid); disengage; }
        fds: list[Finding] = [];
        for ch in [here ->:HasFinding:->][?:Finding] { fds.append(ch); }
        for f in fds {
            print("rank fid " + f.fid);
            if f.reachable { self.best.append(f); }
        }
        disengage;
    }
}

def make_anchor(name: str) -> GraphAnchor {
    a = GraphAnchor(name=name);
    root +>:Contains:+> a;
    return a;
}

def register_machine(anchor: GraphAnchor, mid: str, lane: str, occupied: bool, frozen: bool) -> Machine {
    m = Machine(mid=mid, lane=lane, occupied=occupied, frozen=frozen);
    anchor +>:Contains:+> m;
    return m;
}

def add_state(machine: Machine, sid: str, is_terminal: bool) -> State {
    s = State(sid=sid, is_terminal=is_terminal);
    machine +>:Contains:+> s;
    return s;
}

def add_transition(src: State, dst: State) -> None {
    src +>:Transits:+> dst;
}

def add_finding(machine: Machine, fid: str, impact: int, reachable: bool, reproducible: bool) -> Finding {
    f = Finding(fid=fid, impact=impact, reachable=reachable, reproducible=reproducible);
    machine +>:HasFinding:+> f;
    return f;
}

def reachable_states(machine: Machine) -> list[str] {
    w = machine spawn ReachFromMachine(claimed={}, collected=[]);
    return sorted(w.collected);
}

def reachable_from(machine: Machine, start_sid: str) -> list[str] {
    target: State | None = None;
    cands: list[State] = [];
    for ch in [machine ->:Contains:->][?:State] { cands.append(ch); }
    for s in cands { if s.sid == start_sid { target = s; } }
    if target is None { return []; }
    st = target as State;
    w = st spawn ReachFromState(claimed={}, collected=[]);
    return sorted(w.collected);
}

def rank_findings(anchor: GraphAnchor) -> list[str] {
    w = anchor spawn RankWalker(claimed={}, best=[]);
    # sort by impact descending then fid for determinism
    out: list[str] = [];
    # collect then sort by fid for test determinism; impact ordering is secondary
    bucket: list[Finding] = w.best;
    # simple bubble sort by impact desc
    n = len(bucket);
    for i in range(n) {
        for j in range(n - 1) {
            if bucket[j].impact < bucket[j + 1].impact {
                tmp = bucket[j];
                bucket[j] = bucket[j + 1];
                bucket[j + 1] = tmp;
            }
        }
    }
    for f in bucket { out.append(f.fid); }
    print("rank root");
    return out;
}

