    has cid: str;
    has isTrashed: bool = false;
    has trashedAt: str = "";
}

edge Child {}

walker CollectTrash {
    has claimed: dict[str, bool] = {};
    has found: list[Page] = [];
    can collect with Page entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here);
        print(here.cid);
        kids: list[Page] = [here ->:Child:->][?:Page];
        if len(kids) > 0 {
            for kid in kids {
                visit kid;
            }
        } else {
            disengage;
        }
    }
}

obj PageStore {
    has pages: dict[str, Page] = {};
}

def make_store() -> PageStore {
    s: PageStore = PageStore();
    return s;
}

def create_page(store: PageStore, cid: str, parent_id: str | None = None) -> Page {
    # single owner helper — callers must not write isTrashed directly
    if cid in store.pages {
        return store.pages[cid];
    }
    nd: Page = Page(cid=cid);
    root ++> nd;
    store.pages[cid] = nd;
    if parent_id != None {
        if parent_id in store.pages {
            par: Page = store.pages[parent_id];
            par +>:Child:+> nd;
        }
    }
    return nd;
}

def link_child(store: PageStore, parent_id: str, child_id: str) -> bool {
    if parent_id not in store.pages { return False; }
    if child_id not in store.pages { return False; }
    p: Page = store.pages[parent_id];
    c: Page = store.pages[child_id];
    p +>:Child:+> c;
    return True;
}

def is_trashed(store: PageStore, cid: str) -> bool {
    if cid not in store.pages { return False; }
    return store.pages[cid].isTrashed;
}

def get_trashed_ids(store: PageStore) -> list[str] {
    out: list[str] = [];
    for k in store.pages {
        if store.pages[k].isTrashed {
            out.append(k);
        }
    }
    return out;
}

def trash_single_unsafe(store: PageStore, cid: str) -> bool {
    # explicit non-cascading writer — must not be used for subtree trash
    if cid not in store.pages { return False; }
    nd: Page = store.pages[cid];
    if nd.isTrashed { return True; }
    nd.isTrashed = True;
    nd.trashedAt = "now";
    return True;
}

def recursively_trash(store: PageStore, cid: str) -> list[str] {
    # one cascade, one owner — collect walk then mutate outside walk
    if cid not in store.pages { return []; }
    start: Page = store.pages[cid];
    w = start spawn CollectTrash(claimed={}, found=[]);
    out: list[str] = [];
    for p in w.found {
        if not p.isTrashed {
            p.isTrashed = True;
            p.trashedAt = "now";
        }
        out.append(p.cid);
    }
    return out;
}

# keep raw single-level writers from drifting — AI tool and services call recursively_trash
def trash_many_single_unsafe(store: PageStore, cids: list[str]) -> int {
    cnt: int = 0;
    for cid in cids {
        if trash_single_unsafe(store, cid) {
            cnt += 1;
        }
    }
    return cnt;
}

