```jac
node Root {
    has name: str = "root";
}
node ElfObject {
    has path: str;
    has rpath: list[str] = [];
    has runpath: list[str] = [];
    has needed: list[str] = [];
    has inherited: list[str] = [];
}
edge Dep {}
walker ClosureWalker {
    has entry_root: str = "";
    has claimed: dict[str, bool] = {};
    has findings: list[dict[str, str]] = [];
    has default_dirs: list[str] = [];
    has all_objs: list[ElfObject] = [];
    can step with ElfObject entry {
        ctx_key: str = here.path + "|";
        for p in here.inherited {
            ctx_key += p + ",";
        }
        if ctx_key in self.claimed {
            skip;
        }
        self.claimed[ctx_key] = True;
        print("closure visit " + here.path + " entry=" + self.entry_root);
        search: list[str] = [];
        if len(here.runpath) > 0 {
            for d in here.runpath {
                search.append(d);
            }
        } else {
            for d in here.rpath {
                search.append(d);
            }
            for d in here.inherited {
                search.append(d);
            }
        }
        for d in self.default_dirs {
            search.append(d);
        }
        next_nodes: list[ElfObject] = [];
        seen_next: dict[str, bool] = {};
        for needed in here.needed {
            chosen_path: str = "";
            chosen_node: ElfObject | None = None;
            for d in search {
                for cand in self.all_objs {
                    if _basename(cand.path) != needed {
                        continue;
                    }
                    if _starts_with(cand.path, d) {
                        chosen_path = cand.path;
                        chosen_node = cand;
                        break;
                    }
                }
                if chosen_path != "" {
                    break;
                }
            }
            rec: dict[str, str] = {"entry": self.entry_root, "consumer": here.path, "needed": needed, "provider": chosen_path, "inherited": ",".join(here.inherited), "error": ""};
            if chosen_path == "" {
                rec["error"] = "unresolved";
            }
            self.findings.append(rec);
            if chosen_node is not None {
                # narrow optional before connect
                cn: ElfObject = chosen_node as ElfObject;
                if cn.path not in seen_next {
                    seen_next[cn.path] = True;
                    nxt: list[str] = [];
                    for v in here.inherited {
                        nxt.append(v);
                    }
                    if len(here.runpath) == 0 {
                        for v in here.rpath {
                            nxt.append(v);
                        }
                    }
                    cn.inherited = nxt;
                    next_nodes.append(cn);
                }
            }
        }
        if len(next_nodes) > 0 {
            paths: list[str] = [];
            for n in next_nodes {
                paths.append(n.path);
            }
            sorted_paths: list[str] = sorted(paths);
            ordered: list[ElfObject] = [];
            for p in sorted_paths {
                for n in next_nodes {
                    if n.path == p {
                        ordered.append(n);
                        break;
                    }
                }
            }
            visit :0: ordered else {
                disengage;
            }
        } else {
            disengage;
        }
    }
}
def _basename(p: str) -> str {
    last: int = 0;
    idx: int = 0;
    for ch in p {
        if ch == "/" {
            last = idx + 1;
        }
        idx += 1;
    }
    return p[last:];
}
def _starts_with(s: str, prefix: str) -> bool {
    if len(prefix) == 0 {
        return True;
    }
    if len(s) < len(prefix) {
        return False;
    }
    return s[0:len(prefix)] == prefix;
}
def make_root() -> Root {
    r = Root(name="root");
    return r;
}
def add_object(graph_root: Root, path: str, rpath: list[str] | None = None, runpath: list[str] | None = None, needed: list[str] | None = None) -> ElfObject {
    rp: list[str] = [];
    if rpath is not None {
        for x in rpath {
            rp.append(x);
        }
    }
    rnp: list[str] = [];
    if runpath is not None {
        for x in runpath {
            rnp.append(x);
        }
    }
    nd_needed: list[str] = [];
    if needed is not None {
        for x in needed {
            nd_needed.append(x);
        }
    }
    nd = ElfObject(path=path, rpath=rp, runpath=rnp, needed=nd_needed);
    graph_root ++> nd;
    return nd;
}
def run_closure(graph_root: Root, entry_paths: list[str]) -> list[dict[str, str]] {
    all_objs: list[ElfObject] = [graph_root -->][?:ElfObject];
    combined: list[dict[str, str]] = [];
    for ep in entry_paths {
        target: ElfObject | None = None;
        for o in all_objs {
            if o.path == ep {
                target = o;
                break;
            }
        }
        if target is None {
            continue;
        }
        tn: ElfObject = target as ElfObject;
        tn.inherited = [];
        w = tn spawn ClosureWalker(entry_root=ep, claimed={}, findings=[], default_dirs=["/usr/lib", "/lib"], all_objs=all_objs);
        for f in w.findings {
            combined.append(f);
        }
    }
    flat: list[str] = [];
    for f in combined {
        flat.append(f["entry"] + "|" + f["consumer"] + "|" + f["needed"] + "|" + f["provider"]);
    }
    sorted_flat: list[str] = sorted(flat);
    out: list[dict[str, str]] = [];
    for s in sorted_flat {
        for f in combined {
            key: str = f["entry"] + "|" + f["consumer"] + "|" + f["needed"] + "|" + f["provider"];
            if key == s {
                # remove to handle duplicate keys with different inherited correctly by multiset
                # find first unmatched
                already: bool = False;
                for o in out {
                    if o["entry"] == f["entry"] and o["consumer"] == f["consumer"] and o["needed"] == f["needed"] and o["provider"] == f["provider"] and o["inherited"] == f["inherited"] {
                        if key == s {
                            # allow duplicates only if exact dict not yet added
                            continue;
                        }
                    }
                }
                out.append(f);
                break;
            }
        }
    }
    # fallback if dedup logic missed duplicates, return sorted by flat directly
    if len(out) != len(combined) {
        out = [];
        # simple stable sort by provider then inherited
        # rebuild via flat already sorted, just append first match per flat entry without dedup guard
        used: dict[str, int] = {};
        for s in sorted_flat {
            for f in combined {
                key2: str = f["entry"] + "|" + f["consumer"] + "|" + f["needed"] + "|" + f["provider"];
                if key2 == s {
                    cnt: int = 0;
                    if s in used {
                        cnt = used[s];
                    }
                    # count occurrences of this dict already added
                    cur: int = 0;
                    for o in out {
                        if o["entry"] == f["entry"] and o["consumer"] == f["consumer"] and o["needed"] == f["needed"] {
                            cur += 1;
                        }
                    }
                    if cur == cnt {
                        out.append(f);
                        used[s] = cnt + 1;
                        break;
                    }
                }
            }
        }
    }
    return out;
}
