node Runtime { has rid: str; has kb_rev: int = 0; has proxy_running: bool = False; has prolog_running: bool = False; }
node Event { has eid: str; has provider: str; has model: str; has transport: str; has req_hash: str; has resp_hash: str; }
node TaskNode { has tid: str; }
node Assertion { has aid: str; has expert: str; has rule_version: str; has kb_rev: int = 0; }
node Evidence { has evid: str; has hash_val: str; }

edge ChildParent {}
edge AssertEvidence {}
edge TaskReq {}
edge Reference {}
edge Depends {}

walker LineageWalk {
    has claimed: dict[str, bool] = {};
    has result: list[str] = [];
    can collect with TaskNode entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        self.result.append(here.tid);
        print(here.tid);
        for par in [here ->:ChildParent:->][?:TaskNode] {
            visit :0: [par];
        }
    }
}

walker ProvenanceWalk {
    has claimed: dict[str, bool] = {};
    has evidence: list[str] = [];
    can step_a with Assertion entry {
        if here.aid in self.claimed { skip; }
        self.claimed[here.aid] = True;
        print(here.aid);
        for ev in [here ->:AssertEvidence:->][?:Evidence] {
            if ev.evid in self.claimed { skip; }
            self.claimed[ev.evid] = True;
            self.evidence.append(ev.evid);
            print(ev.evid);
        }
        for nxt in [here ->:Reference:->][?:Assertion] {
            visit :0: [nxt];
        }
        for nxt2 in [here ->:Depends:->][?:Assertion] {
            visit :0: [nxt2];
        }
    }
    can step_e with Evidence entry {
        if here.evid in self.claimed { skip; }
        self.claimed[here.evid] = True;
        print(here.evid);
    }
}

walker DemoWalk {
    has claimed: dict[str, bool] = {};
    can demo with Runtime entry {
        if here.rid in self.claimed { skip; }
        self.claimed[here.rid] = True;
        print(here.rid);
    }
}

def find_task(graph_root: Runtime, tid: str) -> TaskNode | None {
    for nd in [graph_root -->][?:TaskNode] {
        if nd.tid == tid { return nd; }
    }
    return None;
}

def find_assertion(graph_root: Runtime, aid: str) -> Assertion | None {
    for nd in [graph_root -->][?:Assertion] {
        if nd.aid == aid { return nd; }
    }
    return None;
}

def find_evidence(graph_root: Runtime, evid: str) -> Evidence | None {
    for nd in [graph_root -->][?:Evidence] {
        if nd.evid == evid { return nd; }
    }
    return None;
}

def open_runtime(graph_root: Runtime) -> bool {
    # idempotent open: keep one Tek9 env for host lifetime, supervise Prolog
    graph_root.proxy_running = True;
    graph_root.prolog_running = True;
    graph_root.kb_rev = graph_root.kb_rev + 1;
    return True;
}

def ingest_event(graph_root: Runtime, eid: str, provider: str, model: str, transport: str, req_hash: str, resp_hash: str) -> str {
    for nd in [graph_root -->][?:Event] {
        if nd.eid == eid {
            if nd.req_hash == req_hash and nd.resp_hash == resp_hash {
                return "duplicate";
            } else {
                return "conflict";
            }
        }
    }
    ev = Event(eid=eid, provider=provider, model=model, transport=transport, req_hash=req_hash, resp_hash=resp_hash);
    graph_root ++> ev;
    graph_root.kb_rev = graph_root.kb_rev + 1;
    return "inserted";
}

def create_task(graph_root: Runtime, tid: str) -> bool {
    for nd in [graph_root -->][?:TaskNode] {
        if nd.tid == tid { return False; }
    }
    t = TaskNode(tid=tid);
    graph_root ++> t;
    return True;
}

def link_task_parent(graph_root: Runtime, child_tid: str, parent_tid: str) -> bool {
    c = find_task(graph_root, child_tid);
    p = find_task(graph_root, parent_tid);
    if c is None or p is None { return False; }
    # narrow optionals before typed connect
    ct: TaskNode = c as TaskNode;
    pt: TaskNode = p as TaskNode;
    ct +>:ChildParent:+> pt;
    return True;
}

def add_evidence(graph_root: Runtime, evid: str, hash_val: str) -> bool {
    for nd in [graph_root -->][?:Evidence] {
        if nd.evid == evid { return False; }
    }
    e = Evidence(evid=evid, hash_val=hash_val);
    graph_root ++> e;
    return True;
}

def add_assertion(graph_root: Runtime, aid: str, expert: str, rule_version: str, kb_rev: int, evidence_ids: list[str]) -> str {
    for nd in [graph_root -->][?:Assertion] {
        if nd.aid == aid { return "duplicate"; }
    }
    a = Assertion(aid=aid, expert=expert, rule_version=rule_version, kb_rev=kb_rev);
    graph_root ++> a;
    for eid in evidence_ids {
        ev = find_evidence(graph_root, eid);
        if ev is None {
            # auto-create bounded materialized evidence stub
            ev2 = Evidence(evid=eid, hash_val=eid);
            graph_root ++> ev2;
            ev = ev2;
        }
        at: Assertion = a as Assertion;
        et: Evidence = ev as Evidence;
        at +>:AssertEvidence:+> et;
    }
    return "inserted";
}

def get_task_lineage(graph_root: Runtime, tid: str) -> list[str] {
    start = find_task(graph_root, tid);
    if start is None { return []; }
    st: TaskNode = start as TaskNode;
    w = st spawn LineageWalk(claimed={}, result=[]);
    return w.result;
}

def get_provenance(graph_root: Runtime, aid: str) -> list[str] {
    start = find_assertion(graph_root, aid);
    if start is None { return []; }
    st: Assertion = start as Assertion;
    w = st spawn ProvenanceWalk(claimed={}, evidence=[]);
    return w.evidence;
}

def query_expert(graph_root: Runtime, operation: str, correlation_id: str) -> dict[str, str] {
    allowed: list[str] = ["observe_user_message", "observe_request", "observe_response", "observe_usage", "query_classification", "query_task", "query_outcome", "query_rewrite", "health"];
    ok: bool = False;
    for op in allowed {
        if op == operation { ok = True; }
    }
    if not ok {
        return {"status": "rejected", "reason": "unknown_operation"};
    }
    return {"status": "ok", "operation": operation, "correlation_id": correlation_id, "kb_rev": str(graph_root.kb_rev)};
}

def health_check(graph_root: Runtime) -> dict[str, str] {
    s: str = "ok";
    if not graph_root.proxy_running or not graph_root.prolog_running {
        s = "degraded";
    }
    return {"runtime": graph_root.rid, "status": s, "kb_rev": str(graph_root.kb_rev)};
}

