    assert (add_assertion(r, "a2", "rewriter", "v1", 1, ["e2", "e3"]) == "inserted");
    a1 = find_assertion(r, "a1") as Assertion;
    a2 = find_assertion(r, "a2") as Assertion;
    a1 +>:Reference:+> a2;
    # diamond revisit: a1 -> a2 and a1 -> e2 directly, e2 must appear once
    prov = get_provenance(r, "a1");
    assert (sorted(prov) == ["e1", "e2", "e3"]);
    assert (get_provenance(r, "no_such") == []);
