"""nahisaho/aira-synapse#11 — Stage V dictionary persistence before indexing success."""

node Document { has cid: str; has doc_id: str; has corpus_id: str; }
node LexiconEntry { has cid: str; has entry_id: str; has term: str; }
node TermDictionary { has cid: str; has dict_id: str; has settled: bool = False; has stored: list[str] = []; }

edge LexiconEdge {}
edge DictEdge {}

walker BuildWalker {
    has claimed: dict[str, bool] = {};
    has ordered: list[str] = [];
    has stage: str = "not_started";

    can step_doc with Document entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("BuildWalker doc " + here.doc_id);
        self.stage = "local_transaction_running";
        kids: list[LexiconEntry] = [here ->:LexiconEdge:->][?:LexiconEntry];
        dicts: list[TermDictionary] = [here ->:DictEdge:->][?:TermDictionary];
        if len(kids) == 0 {
            self.stage = "dictionary_settlement_pending";
            self.stage = "settled";
            disengage;
        }
        for k in kids {
            self.ordered.append(k.term);
        }
        self.stage = "dictionary_settlement_pending";
        for d in dicts {
            for t in self.ordered {
                d.stored.append(t);
            }
            d.settled = True;
        }
        self.stage = "settled";
        print("built " + here.doc_id);
        visit :0: kids;
    }
    can step_entry with LexiconEntry entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("entry " + here.term);
        kids: list[LexiconEntry] = [here ->:LexiconEdge:->][?:LexiconEntry];
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

walker BackfillWalker {
    has claimed: dict[str, bool] = {};
    has ordered: list[str] = [];
    has stage: str = "not_started";

    can bf_doc with Document entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("BackfillWalker doc " + here.doc_id);
        self.stage = "local_transaction_running";
        kids: list[LexiconEntry] = [here ->:LexiconEdge:->][?:LexiconEntry];
        dicts: list[TermDictionary] = [here ->:DictEdge:->][?:TermDictionary];
        if len(kids) == 0 {
            self.stage = "dictionary_settlement_pending";
            self.stage = "settled";
            disengage;
        }
        for k in kids {
            self.ordered.append(k.term);
        }
        self.stage = "dictionary_settlement_pending";
        for d in dicts {
            for t in self.ordered {
                d.stored.append(t);
            }
            d.settled = True;
        }
        self.stage = "settled";
        print("backfilled " + here.doc_id);
        visit :0: kids;
    }
    can bf_entry with LexiconEntry entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("bf entry " + here.term);
        kids: list[LexiconEntry] = [here ->:LexiconEdge:->][?:LexiconEntry];
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def upsertEntries(dict_node: TermDictionary, entries: list[str]) -> None {
    # synchronous sqlite failure propagation before fulfilled promise
    for e in entries {
        if e == "__fail__" {
            raise Exception("dictionary rejection");
        }
    }
    for e in entries {
        dict_node.stored.append(e);
    }
    dict_node.settled = True;
}

def buildIncremental(graph_root: Document, dict_node: TermDictionary, entries: list[str]) -> dict[str, int] {
    # preserve call position before recomputation: create entries then retain settlement
    for t in entries {
        nd = LexiconEntry(cid=t, entry_id=t, term=t);
        graph_root +>:LexiconEdge:+> nd;
    }
    graph_root +>:DictEdge:+> dict_node;
    # retain settlement exactly once then await
    upsertEntries(dict_node, entries);
    w = graph_root spawn BuildWalker();
    result: dict[str, int] = {};
    result["count"] = len(entries);
    result["settled"] = 1;
    if dict_node.settled == False {
        raise Exception("settlement not fulfilled");
    }
    print("buildIncremental settled");
    return result;
}

def backfill(graph_root: Document, dict_node: TermDictionary) -> dict[str, int] {
    kids: list[LexiconEntry] = [graph_root ->:LexiconEdge:->][?:LexiconEntry];
    ordered: list[str] = [];
    for k in kids {
        ordered.append(k.term);
    }
    if len(ordered) > 0 {
        graph_root +>:DictEdge:+> dict_node;
        upsertEntries(dict_node, ordered);
    }
    w2 = graph_root spawn BackfillWalker();
    res: dict[str, int] = {};
    res["count"] = len(ordered);
    if len(ordered) > 0 {
        res["settled"] = 1;
    } else {
        res["settled"] = 0;
    }
    print("backfill settled");
    return res;
}

