def add_callable(graph_root: Project, cid: str, version: int, effect: str, boundary: str, value_type: str) -> Callable {
    nd: Callable = Callable(cid=cid, version=version, effect=effect, boundary=boundary, value_type=value_type);
    graph_root +>:Owns:+> nd;
    return nd;
