def add_call_edge(graph_root: Project, caller_cid: str, callee_cid: str) -> bool {
    caller: Callable | None = find_callable(graph_root, caller_cid);
    callee: Callable | None = find_callable(graph_root, callee_cid);
    if caller is None { return False; }
    if callee is None { return False; }
    c: Callable = caller as Callable; e: Callable = callee as Callable;
    c +>:Calls:+> e; return True;
}
def get_bounded_closure(graph_root: Project, entry_cid: str, bound: int) -> list[str] {
    nd: Callable | None = find_callable(graph_root, entry_cid);
    if nd is None { return []; }
    start: Callable = nd as Callable;
    w: BoundedClosure = start spawn BoundedClosure(bound=bound, depth={start.cid: 0});
    return sorted(w.result);
}
def get_composed_effects(graph_root: Project, entry_cid: str, bound: int) -> list[str] {
    ids: list[str] = get_bounded_closure(graph_root, entry_cid, bound);
    res: list[str] = [];
    for cid in ids {
        nd: Callable | None = find_callable(graph_root, cid);
        if nd is None { continue; }
        c: Callable = nd as Callable;
        if c.boundary == "exact" { res.append(c.effect); } else { res.append("conservative:" + c.cid); }
    }
    return sorted(res);
}
def get_stale_callers(graph_root: Project, changed_cid: str) -> list[str] {
    nd: Callable | None = find_callable(graph_root, changed_cid);
    if nd is None { return []; }
    start: Callable = nd as Callable;
    w: ReverseClosure = start spawn ReverseClosure();
    out: list[str] = [];
    for cid in w.result { if cid != changed_cid { out.append(cid); } }
    return sorted(out);
}
def apply_at_callsite(graph_root: Project, caller_cid: str, callee_cid: str) -> dict[str, str] {
    res: dict[str, str] = {};
    caller: Callable | None = find_callable(graph_root, caller_cid);
    callee: Callable | None = find_callable(graph_root, callee_cid);
    if caller is None { res["boundary"] = "refused"; res["effect"] = "unknown"; res["value_type"] = "unknown"; return res; }
    if callee is None { res["boundary"] = "refused"; res["effect"] = "unknown"; res["value_type"] = "unknown"; return res; }
    c: Callable = callee as Callable;
    if c.boundary != "exact" { res["boundary"] = "conservative"; res["effect"] = "conservative:" + c.cid; res["value_type"] = "Any"; return res; }
    res["boundary"] = "exact"; res["effect"] = c.effect; res["value_type"] = c.value_type; return res;
}
