node Pkg {
    has pid: str;
    has name: str;
    has version: str;
    has is_root: bool = false;
}
edge Depends {}

walker ProvenanceWalker {
    has claimed: dict[str, bool] = {};
    has cur: list[str] = [];
    has chains: list[list[str]] = [];
    has limit: int = 3;
    can collect with Pkg entry {
        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = true;
        self.cur.append(here.pid);
        print(here.pid);
        if here.is_root {
            snap: list[str] = [];
            for p in self.cur { snap.append(p); }
            if len(self.chains) < self.limit {
                self.chains.append(snap);
            }
        }
        kids: list[Pkg] = [];
        for up in [here <-:Depends:<-][?:Pkg] { kids.append(up); }
        if len(kids) > 0 {
            if len(self.chains) < self.limit {
                visit :0: kids;
            } else {
                disengage;
            }
        } else {
            disengage;
        }
        self.cur.pop();
    }
}

with entry {
    n = Pkg(pid="demo", name="demo", version="0.0.1", is_root=true);
    root ++> n;
    w = n spawn ProvenanceWalker(limit=2);
    print(w.chains);
}

def new_graph() -> dict[str, Pkg] {
    g: dict[str, Pkg] = {};
    return g;
}

def add_package(graph: dict[str, Pkg], pid: str, name: str, version: str, is_root: bool) -> bool {
    if pid in graph { return false; }
    nd = Pkg(pid=pid, name=name, version=version, is_root=is_root);
    graph[pid] = nd;
    root ++> nd;
    return true;
}

def add_dependency(graph: dict[str, Pkg], from_pid: str, to_pid: str) -> bool {
    if from_pid not in graph { return false; }
    if to_pid not in graph { return false; }
    a: Pkg = graph[from_pid];
    b: Pkg = graph[to_pid];
    a +>:Depends:+> b;
    return true;
}

def duplicate_groups(graph: dict[str, Pkg]) -> dict[str, list[str]] {
    groups: dict[str, list[str]] = {};
    out: dict[str, list[str]] = {};
    for pid in graph {
        nd: Pkg = graph[pid];
        if nd.name not in groups {
            bucket: list[str] = [];
            groups[nd.name] = bucket;
        }
        groups[nd.name].append(pid);
    }
    for nm in groups {
        lst: list[str] = groups[nm];
        if len(lst) > 1 {
            out[nm] = lst;
        }
    }
    return out;
}

def provenance(graph: dict[str, Pkg], pid: str, max_chains: int) -> list[list[str]] {
    # shortest/representative reverse chains up to roots, capped
    if pid not in graph { return []; }
    if max_chains <= 0 { return []; }
    start: Pkg = graph[pid];
    w: ProvenanceWalker = start spawn ProvenanceWalker(limit=max_chains);
    res: list[list[str]] = [];
    for c in w.chains { res.append(c); }
    return res;
}

def why_duplicates(graph: dict[str, Pkg], max_chains: int) -> dict[str, dict[str, list[list[str]]]] {
    res: dict[str, dict[str, list[list[str]]]] = {};
    dups: dict[str, list[str]] = duplicate_groups(graph);
    for nm in dups {
        per: dict[str, list[list[str]]] = {};
        pids: list[str] = dups[nm];
        for pid in pids {
            ch: list[list[str]] = provenance(graph, pid, max_chains);
            per[pid] = ch;
        }
        res[nm] = per;
    }
    return res;
}

def format_chains(chains: list[list[str]]) -> list[str] {
    out: list[str] = [];
    for ch in chains {
        s: str = "";
        first: bool = true;
        for pid in ch {
            if first {
                s = pid;
                first = false;
            } else {
                s = s + " <- " + pid;
            }
        }
        out.append(s);
    }
    return out;
}
