```jac
node Issue { has number: int; has url: str; }
node Task { has tid: str; has title: str; }
node AgentSession { has sid: str; has issue_url: str; has slug: str; }
node Stage { has name: str; has stage_kind: str; }

edge Routed {}
edge References {}
edge Assigned {}
edge Depends {}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has collected: list[str] = [];
    can collect with Stage entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        self.collected.append(here.name);
        print(here.name);
        for nxt in [here ->:Depends:->][?:Stage] {
            visit :0: [nxt];
        }
    }
}

walker ResolveWalker {
    has claimed: dict[str, bool] = {};
    has issue_number: int = 0;
    has has_issue: bool = False;
    can start_stage with Stage entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        print(here.name);
        for t in [here <-:Assigned<-][?:Task] {
            visit :0: [t];
        }
        for nxt in [here ->:Depends:->][?:Stage] {
            visit :0: [nxt];
        }
    }
    can follow_task with Task entry {
        if here.tid in self.claimed { skip; }
        self.claimed[here.tid] = True;
        print(here.tid);
        for iss in [here ->:References:->][?:Issue] {
            self.issue_number = iss.number;
            self.has_issue = True;
        }
    }
}

def create_issue(number: int, url: str) -> Issue {
    nd = Issue(number=number, url=url);
    root ++> nd;
    return nd;
}

def create_task(tid: str, title: str) -> Task {
    nd = Task(tid=tid, title=title);
    root ++> nd;
    return nd;
}

def create_session(sid: str, issue_url: str, slug: str) -> AgentSession {
    nd = AgentSession(sid=sid, issue_url=issue_url, slug=slug);
    root ++> nd;
    return nd;
}

def create_stage(name: str, stage_kind: str) -> Stage {
    nd = Stage(name=name, stage_kind=stage_kind);
    root ++> nd;
    return nd;
}

def route_task(session: AgentSession, task: Task, issue: Issue) {
    session +>:Routed:+> task;
    task +>:References:+> issue;
}

def assign_task_to_stage(task: Task, stage: Stage) {
    task +>:Assigned:+> stage;
}

def add_dependency(prev: Stage, nxt: Stage) {
    prev +>:Depends:+> nxt;
}

def extract_sdlc_env_vars(session: AgentSession) -> dict[str, str] {
    env: dict[str, str] = {};
    url = session.issue_url;
    if url != "" {
        parts: list[str] = url.split("/");
        last: str = parts[len(parts) - 1];
        if last != "" {
            env["SDLC_ISSUE_NUMBER"] = last;
            env["SDLC_TRACKING_ISSUE"] = last;
        }
    }
    return env;
}

def resolve_issue_for_stage(stage: Stage) -> int {
    w = stage spawn ResolveWalker(claimed={}, issue_number=0, has_issue=False);
    if w.has_issue {
        return w.issue_number;
    }
    return 0;
}

def get_reachable_stages(stage: Stage) -> list[str] {
    w = stage spawn ReachWalker(claimed={}, collected=[]);
    return w.collected;
}

with entry {
