        self.claimed[here.pid] = true;
        self.out.append(here.pid);
        print(here.pid);
        kids: list[Pkg] = [here ->:Depends:->][?:Pkg];
        if len(kids) > 0 {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}
def make_graph(name: str) -> Graph {
    g = Graph(name=name);
    root ++> g;
    return g;
}
def add_pkg(graph: Graph, pid: str, sig: str) -> Pkg {
    p = Pkg(pid=pid, sig=sig);
    graph +>:Contains:+> p;
    return p;
}
def add_depends(src: Pkg, dst: Pkg) {
    src +>:Depends:+> dst;
}
def get_lineage(graph: Graph, pid: str) -> list[str] {
    fw = graph spawn FindWalker(target=pid);
    found: Pkg | None = fw.found;
    if found is None {
        return [];
    }
    f: Pkg = found as Pkg;
    w = f spawn LineageWalker(claimed={});
    res: list[str] = w.out;
    return sorted(res);
}
def needs_rebuild(graph: Graph, field_pid: str, cur: dict[str, str], prev: dict[str, str]) -> bool {
    ids: list[str] = get_lineage(graph, field_pid);
    if len(ids) == 0 {
        return false;
    }
    for pid in ids {
        c: str = "";
        p: str = "";
        if pid in cur {
            c = cur[pid] as str;
        }
        if pid in prev {
            p = prev[pid] as str;
        }
        if c != p {
            return true;
        }
    }
    return false;
}
def set_frozen(graph: Graph, pid: str, frozen: bool) -> bool {
    fw = graph spawn FindWalker(target=pid);
    found: Pkg | None = fw.found;
    if found is None {
        return false;
    }
    f: Pkg = found as Pkg;
    f.frozen = frozen;
    return true;
}
