    has found: list[str] = [];
    has start_eid: str = "";
    can step with Experiment entry {
        if here.eid in self.claimed { skip; }
        self.claimed[here.eid] = True;
        if here.eid != self.start_eid {
            self.found.append(here.eid);
        }
        for nxt in [here ->:Lineage:->][?:Experiment] {
            if nxt.eid not in self.claimed {
                visit :0: [nxt];
            }
        }
        print("lineage " + here.eid);
    }
}
def find_cell(cid: str) -> Cell | None {
    for cand in [root ->:Contains:->][?:Cell] {
        if cand.cid == cid { return cand; }
    }
    return None;
}
def find_arch(aid: str) -> Arch | None {
    for cand in [root ->:Contains:->][?:Arch] {
        if cand.aid == aid { return cand; }
    }
    return None;
}
def find_exp(eid: str) -> Experiment | None {
    for cand in [root ->:Contains:->][?:Experiment] {
        if cand.eid == eid { return cand; }
    }
    return None;
}
def get_transitive_dependencies(start_cid: str) -> list[str] {
    start: Cell | None = find_cell(start_cid);
    if start == None { return []; }
    st: Cell = start as Cell;
    w: DependsWalker = st spawn DependsWalker(start_cid=start_cid);
    return sorted(w.found);
}
def get_experiment_lineage(start_eid: str) -> list[str] {
    start: Experiment | None = find_exp(start_eid);
    if start == None { return []; }
    st: Experiment = start as Experiment;
    w: LineageWalker = st spawn LineageWalker(start_eid=start_eid);
    return sorted(w.found);
}
def get_pareto_front() -> list[str] {
    cells: list[Cell] = [];
    for c in [root ->:Contains:->][?:Cell] {
        cells.append(c);
    }
    pareto: list[str] = [];
    for c in cells {
        if c.status != "supported" { continue; }
        dominated: bool = False;
        for o in cells {
            if o.status != "supported" { continue; }
            if o.cid == c.cid { continue; }
            if o.cost <= c.cost and o.acc >= c.acc and (o.cost < c.cost or o.acc > c.acc) {
                dominated = True;
                break;
            }
        }
        if not dominated { pareto.append(c.cid); }
    }
    return sorted(pareto);
}
def diff_architectures(aid: str, bid: str) -> dict[str, str] {
    a: Arch | None = find_arch(aid);
    b: Arch | None = find_arch(bid);
    if a == None or b == None {
        res: dict[str, str] = {};
        res["error"] = "unknown_arch";
        return res;
    }
    aa: Arch = a as Arch;
    bb: Arch = b as Arch;
    out: dict[str, str] = {};
    out["family_a"] = aa.family;
    out["family_b"] = bb.family;
    if aa.family == bb.family {
        out["same_family"] = "true";
    } else {
        out["same_family"] = "false";
    }
    return out;
}
def get_failed_cells() -> list[str] {
    out: list[str] = [];
    for c in [root ->:Contains:->][?:Cell] {
        if c.status == "failed" or c.status == "unsupported" {
            out.append(c.cid);
        }
    }
    return sorted(out);
}
