```jac
node Ws { has wid: str; }
node Nd { has nid: str; has wid: str; has kind: str = "folder"; }
edge Contains {}
node Store { has ws_map: dict[str, Ws] = {}; has nd_map: dict[str, Nd] = {}; }

walker ReachWalker {
    has target: str = "";
    has found: bool = false;
    has claimed: dict[str, bool] = {};
    can reach with Nd entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        print(here.nid);
        if here.nid == self.target { self.found = True; }
        kids: list[Nd] = [];
        for ch in [here ->:Contains:->][?:Nd] { kids.append(ch); }
        if len(kids) > 0 { visit :0: kids; } else { disengage; }
    }
}

walker CollectWalker {
    has claimed: dict[str, bool] = {};
    has out: list[str] = [];
    can collect with Nd entry {
        if here.nid in self.claimed { skip; }
        self.claimed[here.nid] = True;
        print(here.nid);
        self.out.append(here.nid);
        kids: list[Nd] = [];
        for ch in [here ->:Contains:->][?:Nd] { kids.append(ch); }
        if len(kids) > 0 { visit :0: kids; } else { disengage; }
    }
}

def new_store() -> Store {
    s = Store();
    root ++> s;
    return s;
}
def create_workspace(store: Store, wid: str) -> str {
    if wid in store.ws_map { return "exists"; }
    ws = Ws(wid=wid);
    root ++> ws;
    store.ws_map[wid] = ws;
    return "ok";
}
def create_node(store: Store, nid: str, wid: str, kind: str = "folder") -> str {
    if nid in store.nd_map { return "exists"; }
    if wid not in store.ws_map { return "no_workspace"; }
    nd = Nd(nid=nid, wid=wid, kind=kind);
    root ++> nd;
    store.nd_map[nid] = nd;
    return "ok";
}
def link_node(store: Store, parent_id: str, child_id: str) -> str {
    if parent_id not in store.nd_map { return "not_found"; }
    if child_id not in store.nd_map { return "not_found"; }
    if parent_id == child_id { return "self_link"; }
    p = store.nd_map[parent_id] as Nd;
    c = store.nd_map[child_id] as Nd;
    if p.wid != c.wid { return "workspace_mismatch"; }
    rw = c spawn ReachWalker(target=parent_id);
    if rw.found { return "cycle"; }
    for ch in [p ->:Contains:->][?:Nd] {
        if ch.nid == child_id { return "already_linked"; }
    }
    p +>:Contains:+> c;
    return "linked";
}
def bfs_contains(store: Store, anc: str, desc: str) -> bool {
    if anc not in store.nd_map { return False; }
    if desc not in store.nd_map { return False; }
    if anc == desc { return True; }
    st = store.nd_map[anc] as Nd;
    rw = st spawn ReachWalker(target=desc);
    return rw.found;
}
def get_workspace_of_node(store: Store, nid: str) -> str {
    if nid not in store.nd_map { return ""; }
    nd = store.nd_map[nid] as Nd;
    return nd.wid;
}
def recursive_delete(store: Store, nid: str) -> int {
    if nid not in store.nd_map { return 0; }
    nd = store.nd_map[nid] as Nd;
    cw = nd spawn CollectWalker();
    # two-phase mutation: collect then disconnect outside walk
    new_map: dict[str, Nd] = {};
    for k in store.nd_map {
        keep: bool = True;
        for d in cw.out {
            if k == d { keep = False; }
        }
        if keep { new_map[k] = store.nd_map[k] as Nd; }
    }
    for k in new_map {
        par = new_map[k] as Nd;
        todel: list[Nd] = [];
        for ch in [par ->:Contains:->][?:Nd] {
            for d in cw.out {
                if ch.nid == d { todel.append(ch); }
            }
        }
        for ch in todel { par -:Contains:-> ch; }
    }
    cnt: int = len(cw.out);
    store.nd_map = new_map;
    return cnt;
}
def export_dot(store: Store) -> str {
    out: str = "digraph {";
    for nid in store.nd_map {
        nd = store.nd_map[nid] as Nd;
        for ch in [nd ->:Contains:->][?:Nd] {
            out = out + nid + "->" + ch.nid + ";";
        }
    }
    out = out + "}";
    return out;
}
with entry {
    st = new_store();
    create_workspace(st, "w1");
    create_node(st, "demo_a", "w1", "folder");
    nd = st.nd_map["demo_a"] as Nd;
    cw = nd spawn CollectWalker();
    print(cw.out);
    root spawn ReachWalker(target="");
    print("demo ready");
}
