"""iss_2600hz-oscillator__patchtogether.live__2054 - foxy bridgeTick field->wavetable with dirty-tracking and lineage reach."""
node PatchGraph { has name: str; }
node FoxyModule { has name: str; has quiesced: bool = false; has tick_count: int = 0; has last_sig: str = ""; has last_input_sig: str = ""; }
node Raster { has name: str; has frozen: bool = false; has content_hash: str = ""; }
node FieldNode { has name: str; has size: int = 256; }
node Wavetable { has name: str; has sig: str = ""; }

edge Owns {}
edge Feeds {}
edge Drives {}
edge Parent {}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    can start with PatchGraph entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for nxt in [here ->:Owns:->][?:FoxyModule] { visit :0: [nxt]; }
        for nxt in [here ->:Owns:->][?:Raster] { visit :0: [nxt]; }
        print("ReachWalker start");
        visit :0: [] else { disengage; }
    }
    can step_mod with FoxyModule entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here.name);
        for nxt in [here ->:Owns:->][?:Raster] { visit :0: [nxt]; }
        for nxt in [here ->:Feeds:->][?:Raster] { visit :0: [nxt]; }
        for nxt in [here ->:Drives:->][?:FieldNode] { visit :0: [nxt]; }
        for nxt in [here ->:Parent:->][?:FoxyModule] { visit :0: [nxt]; }
        print("ReachWalker mod");
    }
    can step_raster with Raster entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here.name);
        for nxt in [here ->:Feeds:->][?:FieldNode] { visit :0: [nxt]; }
        print("ReachWalker raster");
    }
    can step_field with FieldNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here.name);
        for nxt in [here ->:Feeds:->][?:Wavetable] { visit :0: [nxt]; }
        print("ReachWalker field");
    }
    can step_wave with Wavetable entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here.name);
        print("ReachWalker wave");
        visit :0: [] else { disengage; }
    }
}

walker LineageWalker {
    has claimed: dict[str, bool] = {};
    has chain: list[str] = [];
    can collect with FoxyModule entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.chain.append(here.name);
        for par in [here ->:Parent:->][?:FoxyModule] { visit :0: [par]; }
        print("LineageWalker");
    }
}

walker DirtyCheckWalker {
    has claimed: dict[str, bool] = {};
    has hashes: list[str] = [];
    has all_frozen: bool = true;
    can start_check with FoxyModule entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        for r in [here ->:Owns:->][?:Raster] { visit :0: [r]; }
        for r2 in [here ->:Feeds:->][?:Raster] { visit :0: [r2]; }
        print("DirtyCheck start");
        visit :0: [] else { disengage; }
    }
    can check_raster with Raster entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.hashes.append(here.content_hash);
        if here.frozen == false { self.all_frozen = false; }
        print("DirtyCheck raster");
        visit :0: [] else { disengage; }
    }
}

def find_module(graph: PatchGraph, name: str) -> FoxyModule | None {
    for cand in [graph ->:Owns:->][?:FoxyModule] {
        if cand.name == name { return cand; }
    }
    return None;
}

def create_patch(name: str) -> PatchGraph {
    g = PatchGraph(name=name);
    root ++> g;
    return g;
}

def add_module(graph: PatchGraph, mod_name: str) -> FoxyModule {
    existing = find_module(graph, mod_name);
    if existing is not None { return existing; }
    m = FoxyModule(name=mod_name);
    graph +>:Owns:+> m;
    fld = FieldNode(name=mod_name + "_field", size=256);
    wav = Wavetable(name=mod_name + "_wavetable");
    m +>:Drives:+> fld;
    fld +>:Feeds:+> wav;
    root ++> fld;
    root ++> wav;
    return m;
}

def add_raster(graph: PatchGraph, mod_name: str, raster_name: str, frozen: bool) -> Raster | None {
    mod = find_module(graph, mod_name);
    if mod is None { return None; }
    r = Raster(name=raster_name, frozen=frozen, content_hash=raster_name + "#0");
    mod +>:Owns:+> r;
    # connect raster to field for reachability
    for fld in [mod ->:Drives:->][?:FieldNode] { r +>:Feeds:+> fld; }
    root ++> r;
    return r;
}

def set_raster_content(graph: PatchGraph, raster_name: str, content_hash: str) -> bool {
    for r in [graph ->:Owns:->][?:Raster] {
        if r.name == raster_name { r.content_hash = content_hash; return true; }
    }
    # also search via modules
    for m in [graph ->:Owns:->][?:FoxyModule] {
        for r2 in [m ->:Owns:->][?:Raster] {
            if r2.name == raster_name { r2.content_hash = content_hash; return true; }
        }
    }
    return false;
}

def set_quiesce(graph: PatchGraph, mod_name: str, v: bool) -> bool {
    mod = find_module(graph, mod_name);
    if mod is None { return false; }
    mod.quiesced = v;
    return true;
}

def connect_parent(graph: PatchGraph, child: str, parent: str) -> bool {
    c = find_module(graph, child);
    p = find_module(graph, parent);
    if c is None { return false; }
    if p is None { return false; }
    c +>:Parent:+> p;
    return true;
}

def bridge_tick(graph: PatchGraph, mod_name: str) -> str {
    mod = find_module(graph, mod_name);
    if mod is None { return ""; }
    # FACE_QUIESCE: after first paint short-circuit
    if mod.quiesced == true {
        if mod.tick_count > 0 { return mod.last_sig; }
    }
    w = mod spawn DirtyCheckWalker();
    # dirty-tracking: fingerprint raster inputs
    parts: list[str] = [];
    for h in w.hashes { parts.append(h); }
    # build input sig sorted for determinism
    input_sig = "";
    sorted_parts = sorted(parts);
    for s in sorted_parts { input_sig = input_sig + s + "|"; }
    if w.all_frozen == true {
        if input_sig == mod.last_input_sig {
            if mod.last_sig != "" {
                mod.tick_count = mod.tick_count + 1;
                return mod.last_sig;
            }
        }
    }
    # recompute: simulate boxHeightfield3d+boxToField3d+fieldToWavetable
    new_sig = "wavetable:" + mod.name + ":" + input_sig + ":" + str(w.all_frozen);
    # collect phase done, mutate outside walk
    mod.last_sig = new_sig;
    mod.last_input_sig = input_sig;
    mod.tick_count = mod.tick_count + 1;
    # update wavetable node
    for fld in [mod ->:Drives:->][?:FieldNode] {
        for wav in [fld ->:Feeds:->][?:Wavetable] { wav.sig = new_sig; }
    }
    return new_sig;
}

def get_reachable(graph: PatchGraph, mod_name: str) -> list[str] {
    mod = find_module(graph, mod_name);
    if mod is None { return []; }
    w = mod spawn ReachWalker();
    return w.found;
}

def get_lineage(graph: PatchGraph, mod_name: str) -> list[str] {
    mod = find_module(graph, mod_name);
    if mod is None { return []; }
    w = mod spawn LineageWalker();
    return w.chain;
}

