test "diamond_revisit_reach_adversarial" {
    g = create_patch("diamond_test");
    a = add_module(g, "A");
    b = add_module(g, "B");
    c = add_module(g, "C");
    d = add_module(g, "D");
    # diamond: A -> B -> D and A -> C -> D, plus extra edge insertion order to trigger revisit before deep first-visit
    # use Parent edges to form lineage diamond for reachability
    assert connect_parent(g, "B", "D") == true;
    assert connect_parent(g, "C", "D") == true;
    # adversarial order: connect A->C first, then A->B so C subtree visited first, B revisit of D should be skipped
    assert connect_parent(g, "A", "C") == true;
    assert connect_parent(g, "A", "B") == true;
    got = get_reachable(g, "A");
    # sorted multiset check - order unspecified
    assert sorted(got) == sorted(["A", "B", "C", "D"]);
    # second diamond via Feeds through rasters - ensure claim-map prevents double count
    r1 = add_raster(g, "A", "r1", true);
    r2 = add_raster(g, "B", "r2", true);
    got2 = get_reachable(g, "A");
    assert "r1" in got2;
}

test "unknown_id_tolerance" {
    g = create_patch("unknown_test");
    m = add_module(g, "foxy");
    r = add_raster(g, "foxy", "ra", false);
    assert get_reachable(g, "ghost_mod") == [];
    assert get_lineage(g, "ghost_mod") == [];
    assert bridge_tick(g, "ghost_mod") == "";
    assert set_quiesce(g, "ghost_mod", true) == false;
    assert set_raster_content(g, "no_such_raster", "hash") == false;
    assert connect_parent(g, "ghost", "foxy") == false;
    assert connect_parent(g, "foxy", "ghost") == false;
    assert add_raster(g, "ghost", "rX", false) is None;
}

test "dirty_tracking_skips_recompute_when_frozen" {
    g = create_patch("dirty_test");
    m = add_module(g, "foxy");
    ra = add_raster(g, "foxy", "ra", true);
    rb = add_raster(g, "foxy", "rb", true);
    rc = add_raster(g, "foxy", "rc", true);
    sig1 = bridge_tick(g, "foxy");
    assert sig1 != "";
    # second tick with identical frozen inputs should be skipped (same sig, tick_count still increments but no recompute)
    sig2 = bridge_tick(g, "foxy");
    assert sig2 == sig1;
    # change one raster content -> must recompute
    assert set_raster_content(g, "rb", "rb#1") == true;
    sig3 = bridge_tick(g, "foxy");
    assert sig3 != sig1;
    # not frozen -> always recompute even if hash same (all_frozen false disables skip)
    rd = add_raster(g, "foxy", "rd", false);
    sig4 = bridge_tick(g, "foxy");
    sig5 = bridge_tick(g, "foxy");
    assert sig4 != sig3;
}

test "quiesce_short_circuits_after_first_tick" {
    g = create_patch("quiesce_test");
    m = add_module(g, "foxy");
    ra = add_raster(g, "foxy", "ra", false);
    sig1 = bridge_tick(g, "foxy");
    assert sig1 != "";
    assert set_quiesce(g, "foxy", true) == true;
    # modify raster after quiesce - should still return cached sig
    assert set_raster_content(g, "ra", "ra#changed") == true;
    sig2 = bridge_tick(g, "foxy");
    assert sig2 == sig1;
    # another tick still cached
    sig3 = bridge_tick(g, "foxy");
    assert sig3 == sig1;
}

test "lineage_cycle_and_field_reach" {
    g = create_patch("cycle_test");
    fa = add_module(g, "foxyA");
    fb = add_module(g, "foxyB");
    fc = add_module(g, "foxyC");
    assert connect_parent(g, "foxyA", "foxyB") == true;
    assert connect_parent(g, "foxyB", "foxyC") == true;
    # create cycle foxyC -> foxyA
    assert connect_parent(g, "foxyC", "foxyA") == true;
    chain = get_lineage(g, "foxyA");
    # claim-map + skip must prevent infinite loop, chain contains each once
    assert sorted(chain) == sorted(["foxyA", "foxyB", "foxyC"]);
    assert len(chain) == 3;
    # reach also handles cycle
    reach = get_reachable(g, "foxyA");
    assert "foxyA" in reach;
    assert "foxyB" in reach;
    assert "foxyC" in reach;
    # ensure field and wavetable reachable through Drives/Feeds
    # each module drives its own field/wavetable
    assert "foxyA_field" in reach or "foxyB_field" in reach;
}
