```jac
node AppRuntime { has gen: int = 0; has cfg_ver: int = 0; }
node Component { has cid: str; has condition_key: str = ""; has condition_expected: str = ""; }
node ConfigFact { has key: str; has value: str; }
edge Depends {}
edge Anchors {}
edge Holds {}

walker EffectiveWalker {
    has claimed: dict[str, bool] = {};
    has config_map: dict[str, str] = {};
    has effective: list[str] = [];
    can start with AppRuntime entry {
        print("effective start");
        kids: list[Component] = [here ->:Anchors:->][?:Component];
        visit :0: kids else { disengage; }
    }
    can step with Component entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print(here.cid);
        enable: bool = True;
        if here.condition_key != "" {
            if here.condition_key in self.config_map {
                if self.config_map[here.condition_key] != here.condition_expected {
                    enable = False;
                }
            } else {
                enable = False;
            }
        }
        if enable {
            self.effective.append(here.cid);
        }
        nxt: list[Component] = [here ->:Depends:->][?:Component];
        visit :0: nxt else { disengage; }
    }
}
walker AffectedWalker {
    has changed_key: str = "";
    has claimed: dict[str, bool] = {};
    has affected: list[str] = [];
    can start with AppRuntime entry {
        print("affected start");
        seeds: list[Component] = [];
        all: list[Component] = [here ->:Anchors:->][?:Component];
        for c in all {
            if c.condition_key == self.changed_key {
                seeds.append(c);
            }
        }
        visit :0: seeds else { disengage; }
    }
    can collect with Component entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print(here.cid);
        self.affected.append(here.cid);
        rev: list[Component] = [here <-:Depends:->][?:Component];
        visit :0: rev else { disengage; }
    }
}
walker ReachWalker {
    has origin: str = "";
    has claimed: dict[str, bool] = {};
    has found: bool = False;
    can reach with Component entry {
        if here.cid in self.claimed {
            if here.cid == self.origin {
                self.found = True;
            }
            skip;
        }
        self.claimed[here.cid] = True;
        print(here.cid);
        nxt: list[Component] = [here ->:Depends:->][?:Component];
        visit :0: nxt else { disengage; }
    }
}
def find_component(graph_root: AppRuntime, cid: str) -> Component | None {
    comps: list[Component] = [graph_root ->:Anchors:->][?:Component];
    for c in comps {
        if c.cid == cid { return c; }
    }
    return None;
}
def find_config(graph_root: AppRuntime, key: str) -> ConfigFact | None {
    cfgs: list[ConfigFact] = [graph_root ->:Holds:->][?:ConfigFact];
    for cf in cfgs {
        if cf.key == key { return cf; }
    }
    return None;
}
def make_runtime() -> AppRuntime {
    rt = AppRuntime(gen=0, cfg_ver=0);
    root ++> rt;
    return rt;
}
def add_component(graph_root: AppRuntime, cid: str, condition_key: str, condition_expected: str) -> Component {
    nd = Component(cid=cid, condition_key=condition_key, condition_expected=condition_expected);
    graph_root +>:Anchors:+> nd;
    return nd;
}
def add_dependency(graph_root: AppRuntime, from_cid: str, to_cid: str) -> bool {
    src = find_component(graph_root, from_cid);
    dst = find_component(graph_root, to_cid);
    if src is None { return False; }
    if dst is None { return False; }
    src +>:Depends:+> dst;
    return True;
}
def set_config(graph_root: AppRuntime, key: str, value: str) -> None {
    cf = find_config(graph_root, key);
    if cf is None {
        nc = ConfigFact(key=key, value=value);
        graph_root +>:Holds:+> nc;
    } else {
        cf.value = value;
    }
}
def get_effective(graph_root: AppRuntime) -> list[str] {
    cfgs: list[ConfigFact] = [graph_root ->:Holds:->][?:ConfigFact];
    cmap: dict[str, str] = {};
    for cf in cfgs { cmap[cf.key] = cf.value; }
    w = graph_root spawn EffectiveWalker(claimed={}, config_map=cmap, effective=[]);
    return sorted(w.effective);
}
def get_affected(graph_root: AppRuntime, changed_key: str) -> list[str] {
    w = graph_root spawn AffectedWalker(changed_key=changed_key, claimed={}, affected=[]);
    return sorted(w.affected);
}
def check_cycle(graph_root: AppRuntime) -> bool {
    comps: list[Component] = [graph_root ->:Anchors:->][?:Component];
    for c in comps {
        rw = c spawn ReachWalker(origin=c.cid, claimed={}, found=False);
        if rw.found { return True; }
    }
    return False;
}
def plan_transition(graph_root: AppRuntime, changed_key: str, new_value: str) -> dict[str, str] {
    before: list[str] = get_effective(graph_root);
    bef_set: dict[str, bool] = {};
    for b in before { bef_set[b] = True; }
    cfgs: list[ConfigFact] = [graph_root ->:Holds:->][?:ConfigFact];
    tmp: dict[str, str] = {};
    for cf in cfgs { tmp[cf.key] = cf.value; }
    tmp[changed_key] = new_value;
    w = graph_root spawn EffectiveWalker(claimed={}, config_map=tmp, effective=[]);
    after: list[str] = w.effective;
    aft_set: dict[str, bool] = {};
    for a in after { aft_set[a] = True; }
    plan: dict[str, str] = {};
    for b in before {
        if b in aft_set { plan[b] = "retain"; } else { plan[b] = "remove"; }
    }
    for a in after {
        if a not in bef_set { plan[a] = "add"; }
    }
    return plan;
}
def commit_config(graph_root: AppRuntime, key: str, value: str) -> bool {
    if check_cycle(graph_root) { return False; }
    cfgs: list[ConfigFact] = [graph_root ->:Holds:->][?:ConfigFact];
    tmp: dict[str, str] = {};
    for cf in cfgs { tmp[cf.key] = cf.value; }
    tmp[key] = value;
    # validate effective graph can be built
    w = graph_root spawn EffectiveWalker(claimed={}, config_map=tmp, effective=[]);
    # if walker succeeded, publish
    cf = find_config(graph_root, key);
    if cf is None {
        nc = ConfigFact(key=key, value=value);
        graph_root +>:Holds:+> nc;
    } else {
        cf.value = value;
    }
    if check_cycle(graph_root) { return False; }
    graph_root.gen += 1;
    graph_root.cfg_ver += 1;
    print("commit ok");
    return True;
}
