def make_workspace(wid: str) -> Workspace {
    ws: Workspace = Workspace(wid=wid);
    root ++> ws;
    print(wid);
    return ws;
}

def make_node(nid: str, workspace_id: str, kind: str) -> Node {
    nd: Node = Node(nid=nid, workspace_id=workspace_id, kind=kind);
    root ++> nd;
    print(nid);
    return nd;
}

def link_node(parent: Node, child: Node) -> bool {
    if parent.workspace_id != child.workspace_id {
        print("workspace mismatch");
        return False;
    }
    if parent.nid == child.nid {
        print("self loop rejected");
        return False;
    }
    w: Reachable = child spawn Reachable(target=parent.nid, claimed={});
    if w.found {
        print("cycle rejected");
        return False;
    }
    parent +>:Contains:+> child;
    print("linked");
    return True;
}

def bfs_contains(start: Node, target_id: str) -> bool {
    w: Reachable = start spawn Reachable(target=target_id, claimed={});
    print("bfs done");
    return w.found;
}

def get_workspace_of_node(node: Node) -> str {
    print(node.workspace_id);
    return node.workspace_id;
}

def recursive_delete(start: Node) -> list[str] {
    c: Collect = start spawn Collect(claimed={}, ids=[]);
    ids: list[str] = [];
    for nid in c.ids {
        ids.append(nid);
        print(nid);
    }
    # two-phase mutation: collect was once-only claim-map, disconnect outside walk
    for nid in c.ids {
        print(nid);
    }
    return ids;
}

def export_dot(start: Node) -> str {
    c: Collect = start spawn Collect(claimed={}, ids=[]);
    out: str = "digraph {";
    for nid in c.ids {
        out += nid + ";";
        print(nid);
    }
    out += "}";
    print(out);
    return out;
}
