test "link rejects cycle and diamond revisit" {
    ws: Workspace = make_workspace("w1");
    a: Node = make_node("a", "w1", "folder");
    b: Node = make_node("b", "w1", "folder");
    c: Node = make_node("c", "w1", "folder");
    d: Node = make_node("d", "w1", "folder");
    assert(link_node(a, b) == True);
    assert(link_node(a, c) == True);
