    assert(link_node(b, d) == True);
    assert(link_node(c, d) == True);
    assert(bfs_contains(a, "d") == True);
    # cycle via descendant: d is descendant of a, so d->a must be rejected
    assert(link_node(d, a) == False);
    assert(link_node(c, a) == False);
