    return out;
}
def get_transitive_dependencies(start: Target) -> list[str] {
    w = start spawn Discover(claimed={}, order=[]);
    return w.order;
}
def is_reachable(start: Target, target_name: str) -> bool {
    if start.name == target_name {
        return True;
    }
    w = start spawn ReachCheck(target_name=target_name, claimed={}, found=False);
    return w.found;
}
def compute_graph(graph_root: GraphRoot, roots: list[Target]) -> list[str] {
    all: list[str] = [];
    seen: dict[str, bool] = {};
    for r in roots {
        deps: list[str] = get_transitive_dependencies(r);
        for n in deps {
            if n not in seen {
                seen[n] = True;
                all.append(n);
            }
        }
    }
    return sorted(all);
}
