        for kid in [here ->:Holds:->][?:Cell] {
            visit :0: [kid];
        }
        print("collect start");
    }
    can step with Cell entry {
        if here.cell_id in self.claimed { skip; }
        self.claimed[here.cell_id] = True;
        self.out.append(here);
        print(here.cell_id);
    }
}
walker ReachWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    can step with Cell entry {
        if here.cell_id in self.claimed { skip; }
        self.claimed[here.cell_id] = True;
        self.found.append(here.cell_id);
        for nxt in [here ->:Depends:->][?:Cell] {
            visit :0: [nxt];
        }
        for nxt2 in [here ->:Lineage:->][?:Cell] {
            visit :0: [nxt2];
        }
        print(here.cell_id);
    }
}
walker LineageWalk {
    has claimed: dict[str, bool] = {};
    has chain: list[str] = [];
    can step with Cell entry {
        if here.cell_id in self.claimed { skip; }
        self.claimed[here.cell_id] = True;
        self.chain.append(here.cell_id);
        for par in [here <-:Lineage:->][?:Cell] {
            visit :0: [par];
        }
        print(here.cell_id);
    }
}

def find_cell(graph_root: ExplorerRoot, cell_id: str) -> Cell | None {
    for cand in [graph_root ->:Holds:->][?:Cell] {
        if cand.cell_id == cell_id {
            return cand;
        }
    }
    return None;
}
def create_explorer() -> ExplorerRoot {
    r: ExplorerRoot = ExplorerRoot(dummy=True);
    return r;
}
def add_cell(graph_root: ExplorerRoot, cell_id: str, arch: str, cost: float, accuracy: float, status: str, parent_id: str | None = None, depends_on: str | None = None) -> bool {
    for c in [graph_root ->:Holds:->][?:Cell] {
        if c.cell_id == cell_id {
            return False;
        }
    }
    nd: Cell = Cell(cell_id=cell_id, arch=arch, cost=cost, accuracy=accuracy, status=status);
    graph_root +>:Holds:+> nd;
    if parent_id is not None {
        p = find_cell(graph_root, parent_id);
        if p is not None {
            p +>:Lineage:+> nd;
        }
    }
    if depends_on is not None {
        d = find_cell(graph_root, depends_on);
        if d is not None {
            d +>:Depends:+> nd;
        }
    }
    return True;
}
def get_pareto_front(graph_root: ExplorerRoot) -> list[str] {
    w = graph_root spawn CollectAll(claimed={}, out=[]);
    all_cells: list[Cell] = w.out;
    pareto: list[str] = [];
    for cand in all_cells {
        dominated: bool = False;
        for other in all_cells {
            if other.cell_id == cand.cell_id { continue; }
            if other.accuracy >= cand.accuracy and other.cost <= cand.cost {
                if other.accuracy > cand.accuracy or other.cost < cand.cost {
                    dominated = True;
                    break;
                }
            }
        }
        if not dominated {
            pareto.append(cand.cell_id);
        }
    }
    pareto = sorted(pareto);
    return pareto;
}
def get_lineage(graph_root: ExplorerRoot, cell_id: str) -> list[str] {
    target = find_cell(graph_root, cell_id);
    if target is None {
        return [];
    }
    w = target spawn LineageWalk(claimed={}, chain=[]);
    res: list[str] = w.chain;
    res = sorted(res);
    return res;
}
def get_reachable(graph_root: ExplorerRoot, start_id: str) -> list[str] {
    start = find_cell(graph_root, start_id);
    if start is None {
        return [];
    }
    w = start spawn ReachWalk(claimed={}, found=[]);
    out: list[str] = w.found;
    out = sorted(out);
    return out;
}
def get_failures(graph_root: ExplorerRoot) -> list[str] {
    w = graph_root spawn CollectAll(claimed={}, out=[]);
    all_cells: list[Cell] = w.out;
    fails: list[str] = [];
    for c in all_cells {
        if c.status == "failed" or c.status == "unsupported" {
            fails.append(c.cell_id);
        }
    }
    fails = sorted(fails);
    return fails;
}
def diff_architectures(graph_root: ExplorerRoot, a_id: str, b_id: str) -> dict[str, str] {
    res: dict[str, str] = {};
    a = find_cell(graph_root, a_id);
    b = find_cell(graph_root, b_id);
    if a is None or b is None {
        return res;
    }
    if a.arch != b.arch {
        res["from"] = a.arch;
        res["to"] = b.arch;
    }
    return res;
}
def explain_mutation(graph_root: ExplorerRoot, cell_id: str) -> str {
    target = find_cell(graph_root, cell_id);
    if target is None {
        return "unknown";
    }
    parents: list[Cell] = [];
    for p in [target <-:Lineage:->][?:Cell] {
        parents.append(p);
    }
    if len(parents) == 0 {
        return "origin:" + target.arch;
    }
    par = parents[0];
    if par.arch == target.arch {
        return "no_change";
    }
    return par.arch + "->" + target.arch;
}
