edge Contains {}
edge RDep {}

walker ChainCollect {
    has claimed: dict[str, bool] = {};
    has parent: dict[str, str] = {};
    has chains: list[list[str]] = [];
    has cap: int = 5;
    has start_pid: str = "";
    can collect with Pkg entry {
        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
        print(here.pid);
        if here.is_root {
            chain: list[str] = [];
            chain.append(here.pid);
            cur: str = here.pid;
            cnt: int = 0;
            while cur != self.start_pid {
                if cur in self.parent {
                    cur = self.parent[cur];
                    chain.append(cur);
                } else { break; }
                cnt += 1;
                if cnt > 100 { break; }
            }
            rev: list[str] = [];
            idx: int = len(chain) - 1;
            while idx >= 0 {
                rev.append(chain[idx]);
                idx -= 1;
            }
            if len(self.chains) < self.cap {
                self.chains.append(rev);
            }
        }
        kids: list[Pkg] = [];
        for nxt in [here ->:RDep:->][?:Pkg] {
            if nxt.pid not in self.claimed {
                self.parent[nxt.pid] = here.pid;
                kids.append(nxt);
            }
        }
        visit :0: kids else { disengage; }
    }
}

walker DemoWalker {
    has claimed: dict[str, bool] = {};
    can demo_graph with Graph entry {
        if here.gid in self.claimed { skip; }
        self.claimed[here.gid] = True;
        print(here.gid);
        kids: list[Pkg] = [];
        for p in [here ->:Contains:->][?:Pkg] { kids.append(p); }
        visit :0: kids else { disengage; }
    }
    can demo_pkg with Pkg entry {
        if here.pid in self.claimed { skip; }
        self.claimed[here.pid] = True;
        print(here.pid);
        disengage;
    }
}

def build_graph(entries: list[dict]) -> Graph {
    g: Graph = Graph(gid="lock");
    root ++> g;
    mp: dict[str, Pkg] = {};
    for e in entries {
        pid: str = e["pid"] as str;
        nm: str = e["name"] as str;
        ver: str = e["version"] as str;
        isr: bool = e["is_root"] as bool;
        nd: Pkg = Pkg(pid=pid, name=nm, version=ver, is_root=isr);
        g +>:Contains:+> nd;
        mp[pid] = nd;
    }
    for e in entries {
        pid: str = e["pid"] as str;
        deps: list[str] = e["deps"] as list[str];
        if pid not in mp { continue; }
        src: Pkg = mp[pid] as Pkg;
        for dep_pid in deps {
            if dep_pid in mp {
                dep_node: Pkg = mp[dep_pid] as Pkg;
                dep_node +>:RDep:+> src;
            } else {
                print(dep_pid);
            }
        }
    }
    print(g.gid);
    return g;
}

def duplicate_names(g: Graph) -> list[str] {
    pkgs: list[Pkg] = [];
    for p in [g ->:Contains:->][?:Pkg] { pkgs.append(p); }
    counts: dict[str, int] = {};
    for p in pkgs {
        if p.name in counts {
            counts[p.name] = counts[p.name] + 1;
        } else {
            counts[p.name] = 1;
        }
    }
    res: list[str] = [];
    for n in counts {
        if counts[n] > 1 { res.append(n); }
    }
    print("dups");
    return sorted(res);
}

def why_chains(g: Graph, target_name: str, cap: int) -> dict[str, list[list[str]]] {
    targets: list[Pkg] = [];
    for p in [g ->:Contains:->][?:Pkg] {
        if p.name == target_name { targets.append(p); }
    }
    empty: dict[str, list[list[str]]] = {};
    if len(targets) == 0 {
        print("unknown");
        return empty;
    }
    result: dict[str, list[list[str]]] = {};
    for t in targets {
        w = t spawn ChainCollect(claimed={}, parent={}, chains=[], cap=cap, start_pid=t.pid);
        copy: list[list[str]] = [];
        for ch in w.chains {
            inner: list[str] = [];
            for pid in ch { inner.append(pid); }
            copy.append(inner);
        }
        result[t.pid] = copy;
        print(t.pid);
    }
    return result;
}

def format_chains(chains: dict[str, list[list[str]]]) -> str {
    out: str = "";
    for pid in chains {
        lst: list[list[str]] = chains[pid] as list[list[str]];
        for ch in lst {
            line: str = "";
            first: bool = True;
            for p in ch {
                if first {
                    line = p;
                    first = False;
                } else {
                    line = line + " <- " + p;
                }
            }
            part: str = pid + ": " + line;
            if out == "" {
                out = part;
            } else {
                out = out + "\n" + part;
            }
        }
    }
    print(out);
    return out;
}

with entry {
    g: Graph = Graph(gid="demo");
    root ++> g;
    root spawn DemoWalker(claimed={});
    print("provenance ready");
}
