def make_graph() -> Anchor {
    anch = Anchor(dummy="root");
    root ++> anch;
    return anch;
}

def register_package(graph_anchor: Anchor, name: str, version: str) -> Package {
    for p in [graph_anchor ->:Contains:->][?:Package] {
        if p.name == name {
            p.version = version;
            return p;
        }
    }
    nd = Package(name=name, version=version);
    graph_anchor +>:Contains:+> nd;
    return nd;
}

def find_package(graph_anchor: Anchor, name: str) -> Package | None {
    for p in [graph_anchor ->:Contains:->][?:Package] {
        if p.name == name {
            return p;
        }
    }
    return None;
}

def add_dependency(graph_anchor: Anchor, from_name: str, to_name: str, req: str) -> None {
    src = find_package(graph_anchor, from_name);
    dst = find_package(graph_anchor, to_name);
    if src is None {
        print("unknown source");
        return;
    }
    if dst is None {
        print("unknown dest");
        return;
    }
    src +>:Depends(req=req):+> dst;
}

def set_installed_state(graph_anchor: Anchor, name: str, version: str, deploy_status: str) -> None {
    nd = find_package(graph_anchor, name);
    if nd is None {
        print("unknown package for installed");
        return;
    }
    nd.installed_version = version;
    nd.deploy_status = deploy_status;
}

def version_satisfies(installed: str, req: str) -> bool {
    clean: str = req;
    if clean.startswith("^") {
        clean = clean[1:];
    }
    if installed == clean {
        return True;
    }
    if len(installed) > 0 and len(clean) > 0 {
        if installed[0] == clean[0] {
            return True;
        }
    }
    return False;
}

def plan_install(graph_anchor: Anchor, root_name: str, query_installed: bool) -> dict[str, any] {
    root_pkg = find_package(graph_anchor, root_name);
    if root_pkg is None {
        print("unknown root");
        return {"execution_order": [], "satisfied_dependencies": [], "installed_state_evaluated": query_installed, "execution_order_is_provisional": not query_installed};
    }
    w = root_pkg spawn ClosureWalk(claimed={}, nodes=[]);
    # classify
    to_install: list[Package] = [];
    satisfied: list[dict[str, any]] = [];
    for nd in w.nodes {
        if nd.name == root_name {
            to_install.append(nd);
        } else {
            is_sat: bool = False;
            if query_installed {
                if nd.installed_version != "" and nd.deploy_status == "C" {
                    if version_satisfies(nd.installed_version, "^" + nd.version) {
                        is_sat = True;
                    }
                }
            }
            if is_sat {
                satisfied.append({"application_name": nd.name, "installed_state": {"version": nd.installed_version, "deploy_status": nd.deploy_status}});
            } else {
                to_install.append(nd);
            }
        }
    }
    # topological order for to_install (deps first)
    ordered: list[str] = [];
    added: dict[str, bool] = {};
    remaining: list[Package] = [];
    for p in to_install { remaining.append(p); }
    changed: bool = True;
    while len(remaining) > 0 and changed {
        changed = False;
        candidates: list[Package] = [];
        for cand in remaining {
            ok: bool = True;
            for dep in [cand ->:Depends:->][?:Package] {
                if dep.name in added { continue; }
                is_rem: bool = False;
                for r in remaining {
                    if r.name == dep.name { is_rem = True; }
                }
                if is_rem { ok = False; }
            }
            if ok { candidates.append(cand); }
        }
        # sort candidates by name for determinism
        i: int = 0;
        n: int = len(candidates);
        while i < n {
            j: int = i + 1;
            while j < n {
                if candidates[j].name < candidates[i].name {
                    tmp = candidates[i];
                    candidates[i] = candidates[j];
                    candidates[j] = tmp;
                }
                j += 1;
            }
            i += 1;
        }
        if len(candidates) == 0 and len(remaining) > 0 {
            for r in remaining { ordered.append(r.name); }
            remaining = [];
            changed = True;
        } else {
            for c in candidates {
                ordered.append(c.name);
                added[c.name] = True;
                new_rem: list[Package] = [];
                for r in remaining {
                    if r.name != c.name { new_rem.append(r); }
                }
                remaining = new_rem;
                changed = True;
            }
        }
    }
    return {"execution_order": ordered, "satisfied_dependencies": satisfied, "installed_state_evaluated": query_installed, "execution_order_is_provisional": not query_installed};
}

