def is_satisfied(installed_ver: str, required_ver: str) -> bool {
    req: str = required_ver;
    if req.startswith("^") {
        req = req[1:];
    }
    if installed_ver == req { return True; }
    a: list[str] = installed_ver.split(".");
    b: list[str] = required_ver.split(".");
    # strip ^ for b
    if b[0].startswith("^") {
        b[0] = b[0][1:];
    }
    if len(a) == 0 { return False; }
    if len(b) == 0 { return False; }
    if a[0] != b[0] { return False; }
    return True;
}

def plan_install(graph_root: GraphRoot, root_name: str, installed_state: dict[str, dict[str, str]], query_installed: bool) -> dict {
