    if pkg is None {
        return {"execution_order": [], "satisfied_dependencies": [], "installed_state_evaluated": query_installed, "execution_order_is_provisional": not query_installed};
    }
    start: Package = pkg;
    w: ClosureWalker = start spawn ClosureWalker(claimed={}, collected=[]);
    satisfied_map: dict[str, bool] = {};
    satisfied_list: list[dict[str, dict[str, str]]] = [];
    if query_installed {
        for p in w.collected {
            if p.pkg_name == root_name { continue; }
            if p.pkg_name in installed_state {
                rec: dict[str, str] = installed_state[p.pkg_name];
                ver: str = rec["version"];
                status: str = rec["deploy_status"];
                if status == "C" {
                    if is_satisfied(ver, p.pkg_version) {
                        satisfied_map[p.pkg_name] = True;
                        info: dict[str, dict[str, str]] = {"application_name": p.pkg_name, "installed_state": {"version": ver, "deploy_status": status}};
                        # store as generic dict
                        satisfied_list.append(info);
                    }
                }
            }
        }
    }
    filtered: list[str] = [];
    for p in w.collected {
        if p.pkg_name in satisfied_map { continue; }
        filtered.append(p.pkg_name);
    }
    # deps first, root last, deps sorted for determinism
    deps_only: list[str] = [];
    has_root: bool = False;
    for n in filtered {
        if n == root_name { has_root = True; } else { deps_only.append(n); }
    }
    deps_only = sorted(deps_only);
    ordered: list[str] = [];
    for x in deps_only { ordered.append(x); }
    if has_root { ordered.append(root_name); }
    return {"execution_order": ordered, "satisfied_dependencies": satisfied_list, "installed_state_evaluated": query_installed, "execution_order_is_provisional": not query_installed};
}

