def add_callable(graph_root: Project, cid: str, effect: str, result_type: str) -> Callable {
    ex_opt: Callable | None = find_callable(graph_root, cid);
    if ex_opt is not None {
        ex: Callable = ex_opt as Callable;
        return ex;
    }
    summ: str = effect + ":" + result_type;
    nd: Callable = Callable(cid=cid, effect=effect, result_type=result_type, boundary="static", summary=summ);
