def set_boundary(graph_root: Project, cid: str, boundary: str) -> bool {
    f: Callable | None = find_callable(graph_root, cid);
    if f is None { return False; }
    nd: Callable = f as Callable;
    nd.boundary = boundary;
    return True;
}

def add_call_edge(graph_root: Project, caller_cid: str, callee_cid: str, site_id: str) -> bool {
    ca: Callable | None = find_callable(graph_root, caller_cid);
    ce: Callable | None = find_callable(graph_root, callee_cid);
    if ca is None { return False; }
    if ce is None { return False; }
    caller: Callable = ca as Callable;
    callee: Callable = ce as Callable;
    caller +>:Calls(site=site_id):+> callee;
    return True;
}

def get_callable_summary(graph_root: Project, cid: str) -> str {
    f: Callable | None = find_callable(graph_root, cid);
