    nd: Callable = f as Callable;
    return nd.summary;
}

def compose_call_site(graph_root: Project, caller_cid: str, site_id: str) -> str {
    co: Callable | None = find_callable(graph_root, caller_cid);
    if co is None { return "unknown"; }
    caller: Callable = co as Callable;
    kids: list[Callable] = [caller ->:Calls:->][?:Callable];
    for callee in kids {
        if callee.boundary == "dynamic" { return "refused:dynamic"; }
        return caller.effect + "+" + callee.summary;
