def find_callable(graph_root: Project, cid: str) -> Callable | None {
    candidates: list[Callable] = [graph_root ->][?:Callable];
    for c in candidates {
        if c.cid == cid {
            return c;
        }
    }
    return None;
}
def add_callable(graph_root: Project, cid: str, summary: str) -> Callable {
    existing: Callable | None = find_callable(graph_root, cid);
    if existing is not None {
        return existing;
    }
    nd: Callable = Callable(cid=cid, summary=summary);
    graph_root ++> nd;
    return nd;
}
def add_call_edge(graph_root: Project, src: str, dst: str) -> bool {
    s: Callable | None = find_callable(graph_root, src);
    d: Callable | None = find_callable(graph_root, dst);
    if s is None { return False; }
    if d is None { return False; }
    s +>:Calls:+> d;
    return True;
}
def callees_closure(graph_root: Project, start_cid: str, bound: int) -> list[str] {
    s: Callable | None = find_callable(graph_root, start_cid);
    if s is None { return []; }
    w: ForwardClosure = s spawn ForwardClosure(claimed={}, result=[]);
    out: list[str] = [];
    for x in w.result {
        if x != start_cid {
            out.append(x);
        }
    }
    if bound == 0 {
        return [];
    }
    out = sorted(out);
    if bound > 0 {
        limited: list[str] = [];
        i: int = 0;
        for v in out {
            if i < bound {
                limited.append(v);
                i += 1;
            }
        }
        return limited;
    }
    return out;
}
def callers_of(graph_root: Project, start_cid: str) -> list[str] {
    s: Callable | None = find_callable(graph_root, start_cid);
    if s is None { return []; }
    w: ReverseClosure = s spawn ReverseClosure(claimed={}, result=[]);
    out: list[str] = [];
    for x in w.result {
        if x != start_cid {
            out.append(x);
        }
    }
    return sorted(out);
}
def compose_summary(graph_root: Project, start_cid: str) -> str {
    s: Callable | None = find_callable(graph_root, start_cid);
    if s is None { return ""; }
    closure: list[str] = callees_closure(graph_root, start_cid, 100);
    parts: list[str] = [];
    parts.append(s.summary);
    for cid in closure {
        c: Callable | None = find_callable(graph_root, cid);
        if c is not None {
            parts.append(c.summary);
        }
    }
    parts = sorted(parts);
    out: str = "";
    first: bool = True;
    for p in parts {
        if first {
            out = p;
            first = False;
        } else {
            out = out + "+" + p;
        }
    }
    return out;
}
