def add_transition(graph_root: AuditRoot, from_sid: str, to_sid: str, label: str) -> bool {
    frm = find_state(graph_root, from_sid);
    if frm is None {
        return False;
    }
    to = find_state(graph_root, to_sid);
    if to is None {
        return False;
    }
    frm +>:Transition(label=label):+> to;
    return True;
