    for d in [graph_root ->:CONTAINS:->][?:Document] { for s in [d ->:STORED_IN:->][?:DictStore] { s.settled = True; } }
    vals: list[str] = []; for v in w.collected { vals.append(v); }
    svals: list[str] = sorted(vals); res: str = ""; for v in svals { if res == "" { res = v; } else { res = res + "," + v; } }
